  let connections: SystemConnection[] = [];
  let deliveries: DeliveryFreezeBatch[] = [];
  let selectedId: string | null = null;
  let draftPhysicalInstalled = false;
  let placingMode = false;
  let copiedEndpointId: string | null = null;
  let expandedConnId: string | null = null;
  let batchFttResult: { ranAt: string; total: number; passed: number; failed: number; failedNames: string[] } | null = null;
  let notice = '';
  let errorMsg = '';

  async function refresh(): Promise<void> {
    errorMsg = '';
    const [t, devs, conns, dlvs] = await Promise.all([
      adapter.getSpatialTree(),
      adapter.getFloorDevices(E7F_IDS.floorId).catch(() => []),
      adapter.listConnections(E7F_IDS.projectId),
      adapter.listDeliveryBatches(E7F_IDS.floorId),
    ]);
    tree = t;
    devices = devs;
    connections = conns;
    deliveries = dlvs;
    if (!devices.some((d) => d.id === selectedId)) selectedId = devices[0]?.id ?? null;
    const sel = devices.find((d) => d.id === selectedId);
    draftPhysicalInstalled = sel?.physicalInstalled ?? false;
    render();
  }

  function runSingleDeviceFtt(dev: DeviceEntity): void {
    errorMsg = '';
    if (dev.connectivity === 'offline') {
      errorMsg = `单机回读自检未通过（FAIL）：「${dev.name}」当前离线，请先在「网关与数据健康」核查 ${dev.hardwareBinding?.networkAddress ?? '-'} 链路状态。`;
    } else {
      notice = `单机回读自检通过（PASS）：「${dev.name}」指令下发 → 状态回读一致 → 已安全自动恢复原工况。`;
    }
    render();
  }

  function runBatchFtt(): void {
    errorMsg = '';
    const failedDevs = devices.filter((d) => d.connectivity === 'offline');
    const passed = devices.length - failedDevs.length;
    const now = new Date();
    const hh = String(now.getHours()).padStart(2, '0');
    const mm = String(now.getMinutes()).padStart(2, '0');
    const ss = String(now.getSeconds()).padStart(2, '0');
    batchFttResult = {
      ranAt: `${hh}:${mm}:${ss}`,
      total: devices.length,
      passed,
      failed: failedDevs.length,
      failedNames: failedDevs.map((d) => d.name),
    };
    if (failedDevs.length > 0) {
      errorMsg = `全层批量自检（FTT）完成：${passed}/${devices.length} 台通过，${failedDevs.length} 台失败（${failedDevs.map((d) => d.name).join('、')}），其余设备已安全复位。`;
    } else {
      notice = `全层批量自检（FTT）全部通过：${passed}/${devices.length} 台设备指令下发、状态回读一致并已安全复位。`;
    }
    render();
  }

