    const degradedConns = connections.filter((c) => c.status !== 'connected');

    const placedCount = devices.filter((d) => Boolean(d.planPoint)).length;
    const verifiedCount = devices.filter((d) => d.physicalInstalled).length;
    const unverifiedCount = devices.length - verifiedCount;
    const unplacedCount = devices.length - placedCount;

