        errorMsg = '';
        if (c.status === 'connected') {
          notice = `连通性测试通过：「${c.name}」（${c.endpoint}）响应正常，延迟 18 ms。`;
        } else {
          errorMsg = `连通性测试异常：「${c.name}」（${c.endpoint}）超时无应答，建议排查边缘网关端口与 RS485 链路。`;
        }
